#include <vector>
#include <algorithm>

class Solution {
public:
    int minElement(std::vector<int>& nums) {
        int ans = 1e9;
        for (int x : nums) {
            int sum_d = 0;
            int temp = x;
            while (temp > 0) {
                sum_d += temp % 10;
                temp /= 10;
            }
            ans = std::min(ans, sum_d);
        }
        return ans;
    }
};

class Solution {
    public int minElement(int[] nums) {
        int ans = Integer.MAX_VALUE;
        for (int x : nums) {
            int sumD = 0;
            int temp = x;
            while (temp > 0) {
                sumD += temp % 10;
                temp /= 10;
            }
            ans = Math.min(ans, sumD);
        }
        return ans;
    }
}

var minElement = function(nums) {
    let ans = Infinity;
    for (const x of nums) {
        let sumD = 0;
        let temp = x;
        while (temp > 0) {
            sumD += temp % 10;
            temp = Math.floor(temp / 10);
        }
        if (sumD < ans) ans = sumD;
    }
    return ans;
};
